#!/bin/bash
set -e

# 1. Abort the failed rebase
git rebase --abort

# 2. Pull latest
git pull origin main

# 3. Write agent8
echo '' | base64 -d > agents/agent8_identity_pilot.py

# 4. Patch run_suite.py
python3 -c "
src = open('agents/run_suite.py').read()
if '8: ' not in src:
    src = src.replace('7: \"agent7_consensus.py\",', '7: \"agent7_consensus.py\",\n    8: \"agent8_identity_pilot.py\",')
if '5, 7, 8' not in src:
    src = src.replace('[5, 7, 2,', '[5, 7, 8, 2,').replace('[5, 2,', '[5, 7, 8, 2,')
open('agents/run_suite.py', 'w').write(src)
print('run_suite patched')
"

# 5. Commit and push
git add agents/agent8_identity_pilot.py agents/run_suite.py
git commit -m "Add IdentityPilotAdversary (agent8) — Qattice Phase 2 identity pilot red-team"
git push origin main

echo "Done"